import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 * @property {Array<Object>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url:string)=>THREE.Texture }} textureLoader
 * @property {{ load: (url:string)=>Promise<THREE.Object3D> }} glbLoader
 * @property {{ [key:string]: (obj:THREE.Object3D, params:any)=>void }} primitives
 * @property {{ fontAtlas: any }} fontAtlas
 */

/**
 * Creates a textured pricing card plane.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Geometry
  const geometry = new PlaneGeometry(1, 1, 1, 1);

  // Load texture synchronously via cached loader
  const texture = ctx.textureLoader.load(config.assets?.imageUrl || '');

  // Material using node system (MeshBasicNodeMaterial)
  const material = new MeshBasicNodeMaterial({ map: texture });

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.name = config.id || 'pricing-card-2';

  // Placement
  const pos = config.placement?.position ?? [0, 0, 0];
  const rot = config.placement?.rotation ?? [0, 0, 0];
  const scl = config.placement?.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    }
  }

  // Event handlers placeholder
  mesh.userData.handlers = {};

  // Keep track of any GSAP timelines (none for this node, but prepared)
  const timelines = [];

  // Cleanup routine
  mesh.userData.cleanup = () => {
    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // Dispose resources
    geometry.dispose();
    material.dispose();
    // Do not dispose the texture if it may be shared elsewhere
  };

  return mesh;
}
